from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    def dfs(x, y, path):
        nonlocal result
        if len(path) == k:
            result.append(path.copy())
            return

        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                dfs(nx, ny, path + [grid[nx][ny]])

    N = len(grid)
    result = []
    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]])

    # Find the minimum path based on the given criteria
    min_path_values = min(result, key=lambda path: ''.join(map(str, path)))
    return min_path_values

