def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        CAP = sum(1 for char in extension if char.isupper())
        SM = sum(1 for char in extension if char.islower())
        return CAP - SM

    max_strength = float('-inf')
    strongest_extension = None

    for extension in extensions:
        current_strength = calculate_strength(extension)
        if current_strength > max_strength:
            max_strength = current_strength
            strongest_extension = extension

    return f"{class_name}.{strongest_extension}"

from typing import List
def words_in_sentence(sentence: str) -> str:
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        elif n == 2:
            return True
        elif n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # Split the sentence into words
    words = sentence.split()

    # Filter words whose lengths are prime numbers
    prime_length_words = [word for word in words if is_prime(len(word))]

    # Join the filtered words back into a single string
    result = ' '.join(prime_length_words)

    return result

def closest_integer(value):
    """
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15

    Note:
    Rounding away from zero means that if the given number is equidistant
    from two integers, the one you should return is the one that is the
    farthest from zero. For example closest_integer("14.5") should
    return 15 and closest_integer("-14.5") should return -15.
    """
    num = float(value)
    if abs(num) > 1 and num.is_integer():
        return int(num)

    if abs(round(num)) < abs(round(num + 1)):
        return round(num)
    else:
        return round(num + 1) if num > 0 else round(num - 1)

