def convert_list_dictionary(list1, list2, list3):
    """
    Convert more than one list to nested dictionary.

    :param list1: List of keys for nested dictionaries
    :param list2: List of values for nested dictionaries
    :param list3: List of lists where each sublist contains key-value pairs for nested dictionaries within the main dictionaries
    :return: A nested dictionary with keys from list1 and nested dictionaries as values
    """
    result = {}
    for i in range(len(list1)):
        nested_dict = {}
        for j in range(len(list3[i])):
            nested_dict[list3[i][j][0]] = list3[i][j][1]
        result[list1[i]] = nested_dict
    return result

def unique_sublists(lst):
    """
    Count lists within a list. Return a dictionary where every list is converted to a tuple 
    and the value of such tuple is the number of its occurrences in the original list.

    :param lst: List of lists.
    :return: Dictionary mapping tuples from the sublists to their counts.
    """
    sublist_counts = {}
    for sublist in lst:
        # Convert list to tuple to ensure it's hashable and can be used as a key in the dictionary
        tup = tuple(sublist)
        if tup in sublist_counts:
            sublist_counts[tup] += 1
        else:
            sublist_counts[tup] = 1
    return sublist_counts

