def get_total_number_of_sequences(m, n):
    if m < 2 * n:
        return 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # The current sequence must be at least as large as 2 * (j - 1)
            # So we only consider values up to min(i // 2, j)
            for k in range(min(i // 2, j)):
                dp[i][j] += dp[k][j - 1]

    return dp[m][n]

