    dp_down = [arr[i] for i in range(n)]

    # Fill up the dp_up array
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp_up[i] = max(dp_up[i], dp_up[j] + arr[i])

    # Fill down the dp_down array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dp_down[i] = max(dp_down[i], dp_down[j] + arr[i])

    # Find the maximum sum of the bitonic subsequence
    max_sum_bitonic = float('-inf')
    for i in range(n):
        max_sum_bitonic = max(max_sum_bitonic, dp_up[i] + dp_down[i] - arr[i])

    return max_sum_bitonic

