def shell_sort(arr):
    n = len(arr)
    interval = n // 2

    while interval > 0:
        for i in range(interval, n):
            temp = arr[i]
            j = i - interval

            while j >= 0 and temp < arr[j]:
                arr[j + interval] = arr[j]
                j -= interval

            arr[j + interval] = temp

        interval //= 2

    return arr

