    :param arr1: First sorted array.
    :param arr2: Second sorted array.
    :param k: The position of the element to find (1-based index).
    :return: The kth element.
    """
    i = j = 0

    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            k -= 1
            if k == 0:
                return arr1[i]
            i += 1
        else:
            k -= 1
            if k == 0:
                return arr2[j]
            j += 1

    # If there are remaining elements in arr1 or arr2
    if i < len(arr1):
        return arr1[i]
    elif j < len(arr2):
        return arr2[j]

