def amicable_numbers_sum(limit):
    def get_divisors(n):
        divisors = [1]
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return divisors

    def is_amicable(a, b):
        return sum(get_divisors(a)) == b and sum(get_divisors(b)) == a

    sum_of_amicables = 0
    for num in range(1, limit + 1):
        if is_amicable(num, get_divisors(num)[0]):
            sum_of_amicables += num
    return sum_of_amicables

